        self.words = words
    }

    private enum `JSON keys`: String, CodingKey {
        case minimum = "minimum"
        case recommended = "recommended"
        case storeUrl = "storeUrl"
        case minimumOsVersion = "minimumOsVersion"
        case words = "words"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: `JSON keys`.self)
        self.minimum = try container.`value if present at`(.minimum)
        self.recommended = try container.`value if present at`(.recommended)
        self.storeUrl = try container.`value if present at`(.storeUrl)
        self.minimumOsVersion = try container.`value if present at`(.minimumOsVersion)
        self.words = try container.`value if present at`(.words)
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: `JSON keys`.self)
        try container.encodeIfPresent(self.minimum, forKey: .minimum)
        try container.encodeIfPresent(self.recommended, forKey: .recommended)
        try container.encodeIfPresent(self.storeUrl, forKey: .storeUrl)
        try container.encodeIfPresent(self.minimumOsVersion, forKey: .minimumOsVersion)
        try container.encodeIfPresent(self.words, forKey: .words)
    }
}

