/// A value of any JSON shape, as the API sends free-form data; numbers are doubles.
public nonisolated enum JSONValue: Codable, Hashable, Sendable {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])

    public init(from decoder: any Decoder) throws {
        let container = try decoder.singleValueContainer()
        if container.decodeNil() {
            self = .null
        } else if let value = try? container.decode(Bool.self) {
            self = .bool(value)
        } else if let value = try? container.decode(String.self) {
            self = .string(value)
        } else if let value = try? container.decode(Double.self) {
            self = .number(value)
        } else if let value = try? container.decode([JSONValue].self) {
            self = .array(value)
        } else {
            self = .object(try container.decode([String: JSONValue].self))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .null: try container.encodeNil()
        case .bool(let value): try container.encode(value)
        case .number(let value): try container.encode(value)
        case .string(let value): try container.encode(value)
        case .array(let value): try container.encode(value)
        case .object(let value): try container.encode(value)
        }
    }
}

nonisolated extension KeyedDecodingContainer {
    fileprivate func `value at`<Value: Decodable>(_ key: Key) throws -> Value {
        try decode(Value.self, forKey: key)
    }

    fileprivate func `value if present at`<Value: Decodable>(_ key: Key) throws -> Value? {
        try decodeIfPresent(Value.self, forKey: key)
    }

    fileprivate func `corruption at`(_ key: Key, _ description: String) -> DecodingError {
        .dataCorruptedError(forKey: key, in: self, debugDescription: description)
    }
}

nonisolated extension CluenoriAPI {
    private func send(
        _ method: String,
        _ path: String,
        query: [(String, String)] = [],
        body: Data? = nil,
    ) async throws(APIError) -> (data: Data, status: Int) {
        var address = baseURL.absoluteString
        if address.hasSuffix("/") { address.removeLast() }
        address += path
        if !query.isEmpty {
            address += "?" + query.map { "\(Self.escaped($0.0))=\(Self.escaped($0.1))" }.joined(separator: "&")
        }
        guard let url = URL(string: address) else {
            throw .unwritable(reason: "\(address) isn't a URL.")
        }
        var request = URLRequest(url: url)
        request.httpMethod = method
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        if let bearerToken { request.setValue("Bearer \(bearerToken)", forHTTPHeaderField: "Authorization") }
        if let userAgent { request.setValue(userAgent, forHTTPHeaderField: "User-Agent") }
        if let body {
            request.httpBody = body
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        }
        let data: Data
        let response: URLResponse
        do {
            (data, response) = try await transport(request)
        } catch let error as URLError {
            throw .unreachable(error)
        } catch {
            throw .unreachable(URLError(error is CancellationError ? .cancelled : .unknown))
        }
        let status = (response as? HTTPURLResponse)?.statusCode ?? 0
        guard (200..<300).contains(status) else {
            throw Self.failure(status: status, data: data)
        }
        return (data, status)
    }

    private static func failure(status: Int, data: Data) -> APIError {
        guard case .object(let fields)? = try? jsonDecoder().decode(JSONValue.self, from: data),
            case .string(let named)? = fields["_tag"]
        else {
            return .unreadable(status: status, reason: "The answer names no error.")
        }
        do {
            switch named {
            case "ArchiveUnavailable": return .archiveUnavailable(try jsonDecoder().decode(ArchiveUnavailable.self, from: data))
            case "ComponentExists": return .componentExists(try jsonDecoder().decode(ComponentExists.self, from: data))
            case "ComponentNotFound": return .componentNotFound(try jsonDecoder().decode(ComponentNotFound.self, from: data))
            case "DraftUnavailable": return .draftUnavailable(try jsonDecoder().decode(DraftUnavailable.self, from: data))
            case "ErrorGroupNotFound": return .errorGroupNotFound(try jsonDecoder().decode(ErrorGroupNotFound.self, from: data))
            case "FeatureNotFound": return .featureNotFound(try jsonDecoder().decode(FeatureNotFound.self, from: data))
            case "FeedNotFound": return .feedNotFound(try jsonDecoder().decode(FeedNotFound.self, from: data))
            case "GitHubAlreadyConnected": return .gitHubAlreadyConnected(try jsonDecoder().decode(GitHubAlreadyConnected.self, from: data))
            case "IncidentNotFound": return .incidentNotFound(try jsonDecoder().decode(IncidentNotFound.self, from: data))
            case "InviteRejected": return .inviteRejected(try jsonDecoder().decode(InviteRejected.self, from: data))
            case "LogLineNotFound": return .logLineNotFound(try jsonDecoder().decode(LogLineNotFound.self, from: data))
            case "LogMessageNotFound": return .logMessageNotFound(try jsonDecoder().decode(LogMessageNotFound.self, from: data))
            case "MemberExists": return .memberExists(try jsonDecoder().decode(MemberExists.self, from: data))
            case "MemberNotFound": return .memberNotFound(try jsonDecoder().decode(MemberNotFound.self, from: data))
            case "MonitorExists": return .monitorExists(try jsonDecoder().decode(MonitorExists.self, from: data))
            case "MonitorLimitReached": return .monitorLimitReached(try jsonDecoder().decode(MonitorLimitReached.self, from: data))
            case "MonitorNotFound": return .monitorNotFound(try jsonDecoder().decode(MonitorNotFound.self, from: data))
            case "NoPushToken": return .noPushToken(try jsonDecoder().decode(NoPushToken.self, from: data))
            case "NotAllowed": return .notAllowed(try jsonDecoder().decode(NotAllowed.self, from: data))
            case "PairingCodeRejected": return .pairingCodeRejected(try jsonDecoder().decode(PairingCodeRejected.self, from: data))
            case "PasskeyRejected": return .passkeyRejected(try jsonDecoder().decode(PasskeyRejected.self, from: data))
            case "PersonNotFound": return .personNotFound(try jsonDecoder().decode(PersonNotFound.self, from: data))
            case "PhoneKeyRejected": return .phoneKeyRejected(try jsonDecoder().decode(PhoneKeyRejected.self, from: data))
            case "PhoneNotFound": return .phoneNotFound(try jsonDecoder().decode(PhoneNotFound.self, from: data))
            case "ProjectExists": return .projectExists(try jsonDecoder().decode(ProjectExists.self, from: data))
            case "ProjectNotFound": return .projectNotFound(try jsonDecoder().decode(ProjectNotFound.self, from: data))
            case "PromotionInProgress": return .promotionInProgress(try jsonDecoder().decode(PromotionInProgress.self, from: data))
            case "PromotionNotFound": return .promotionNotFound(try jsonDecoder().decode(PromotionNotFound.self, from: data))
            case "PromotionRefused": return .promotionRefused(try jsonDecoder().decode(PromotionRefused.self, from: data))
            case "PromotionUnavailable": return .promotionUnavailable(try jsonDecoder().decode(PromotionUnavailable.self, from: data))
            case "PushNotSetUp": return .pushNotSetUp(try jsonDecoder().decode(PushNotSetUp.self, from: data))
            case "PushRejected": return .pushRejected(try jsonDecoder().decode(PushRejected.self, from: data))
            case "PushUnavailable": return .pushUnavailable(try jsonDecoder().decode(PushUnavailable.self, from: data))
            case "ReleaseNotFound": return .releaseNotFound(try jsonDecoder().decode(ReleaseNotFound.self, from: data))
            case "SdkKeyNotFound": return .sdkKeyNotFound(try jsonDecoder().decode(SdkKeyNotFound.self, from: data))
            case "SignInNotFound": return .signInNotFound(try jsonDecoder().decode(SignInNotFound.self, from: data))
            case "Unauthorized": return .unauthorized(try jsonDecoder().decode(Unauthorized.self, from: data))
            case "VersionPolicyRefused": return .versionPolicyRefused(try jsonDecoder().decode(VersionPolicyRefused.self, from: data))
            case "VersionRefused": return .versionRefused(try jsonDecoder().decode(VersionRefused.self, from: data))
            default: return .unreadable(status: status, reason: "An error this client doesn't know: \(named).")
            }
        } catch {
            return .unreadable(status: status, reason: "\(error)")
        }
    }

    private static func decoded<Value: Decodable>(from answer: (data: Data, status: Int)) throws(APIError) -> Value {
        do {
            return try jsonDecoder().decode(Value.self, from: answer.data)
        } catch {
            throw .unreadable(status: answer.status, reason: "\(error)")
        }
    }

    private static func encoded(_ value: some Encodable) throws(APIError) -> Data {
        do {
            return try jsonEncoder().encode(value)
        } catch {
            throw .unwritable(reason: "\(error)")
        }
    }

    private static let instant = Date.ISO8601FormatStyle(includingFractionalSeconds: true)
    private static let instantInSeconds = Date.ISO8601FormatStyle()

    private static func jsonDecoder() -> JSONDecoder {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .custom { decoder in
            let container = try decoder.singleValueContainer()
            let text = try container.decode(String.self)
            if let date = (try? instant.parse(text)) ?? (try? instantInSeconds.parse(text)) { return date }
            throw DecodingError.dataCorruptedError(in: container, debugDescription: "\(text) isn't an ISO 8601 date-time.")
        }
        decoder.nonConformingFloatDecodingStrategy = .convertFromString(positiveInfinity: "Infinity", negativeInfinity: "-Infinity", nan: "NaN")
        return decoder
    }

    private static func jsonEncoder() -> JSONEncoder {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .custom { date, encoder in
            var container = encoder.singleValueContainer()
            try container.encode(date.formatted(instant))
        }
        encoder.nonConformingFloatEncodingStrategy = .convertToString(positiveInfinity: "Infinity", negativeInfinity: "-Infinity", nan: "NaN")
        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
        return encoder
    }

    private static let unreserved = CharacterSet(charactersIn: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")

    private static func escaped(_ text: String) -> String {
        text.addingPercentEncoding(withAllowedCharacters: unreserved) ?? text
    }

    // A path parameter's value as a segment of its own: escaped, and refused when it is empty, `.`
    // or `..`, which a URL reads as no segment or as a step up the path.
    private static func segment(_ text: String) throws(APIError) -> String {
        guard !text.isEmpty, text != ".", text != ".." else {
            throw .unwritable(reason: "A path parameter of \"\(text)\" isn't a segment of a path.")
        }
        return escaped(text)
    }

    private static func text(_ value: String) -> String { value }
    private static func text(_ value: Date) -> String { value.formatted(instant) }
    private static func text(_ value: Int) -> String { String(value) }
    private static func text(_ value: Double) -> String { String(value) }
    private static func text(_ value: Bool) -> String { value ? "true" : "false" }
    private static func text<Value: RawRepresentable>(_ value: Value) -> String where Value.RawValue == String {
        value.rawValue
    }
}
